import React, {useState} from 'react'
import PropTypes from 'prop-types'
import {FormattedMessage} from 'react-intl'
import {Button, Divider, Stack, Text} from '@salesforce/retail-react-app/app/components/shared/ui'
import LoginFields from '@salesforce/retail-react-app/app/components/forms/login-fields'
import StandardLogin from '@salesforce/retail-react-app/app/components/standard-login'
import SocialLogin from '@salesforce/retail-react-app/app/components/social-login'

const noop = () => {}
const PasswordlessLogin = ({
    form,
    handleForgotPasswordClick,
    handlePasswordlessLoginClick,
    isSocialEnabled = false,
    idps = [],
    setLoginType: _setLoginType = noop
}) => {
    const [showPasswordView, setShowPasswordView] = useState(false)

    const handlePasswordButton = async (e) => {
        const isValid = await form.trigger()
        // Manually trigger the browser native form validations
        const domForm = e.target.closest('form')
        if (isValid && domForm.checkValidity()) {
            setShowPasswordView(true)
        } else {
            domForm.reportValidity()
        }
    }

    return (
        <>
            {(!showPasswordView || form.formState.errors.email) && (
                <Stack spacing={6} paddingLeft={4} paddingRight={4}>
                    <LoginFields
                        form={form}
                        hidePassword={true}
                        handleForgotPasswordClick={handleForgotPasswordClick}
                    />
                    <Button
                        type="submit"
                        onClick={(e) => {
                            handlePasswordlessLoginClick(e)
                            form.clearErrors('global')
                        }}
                        isLoading={form.formState.isSubmitting}
                    >
                        <FormattedMessage
                            defaultMessage="Continue"
                            id="login_form.button.continue_securely"
                        />
                    </Button>
                    <Divider />
                    <Text align="center" fontSize="sm">
                        <FormattedMessage
                            defaultMessage="Or Login With"
                            id="login_form.message.or_login_with"
                        />
                    </Text>
                    <Stack spacing={4}>
                        <Button
                            onClick={handlePasswordButton}
                            borderColor="gray.500"
                            color="blue.600"
                            variant="outline"
                        >
                            <FormattedMessage
                                defaultMessage="Password"
                                id="login_form.button.password"
                            />
                        </Button>
                        {isSocialEnabled && <SocialLogin form={form} idps={idps} />}
                    </Stack>
                </Stack>
            )}
            {showPasswordView && !form.formState.errors.email && (
                <StandardLogin
                    form={form}
                    handleForgotPasswordClick={handleForgotPasswordClick}
                    setShowPasswordView={setShowPasswordView}
                    hideEmail={true}
                />
            )}
        </>
    )
}

PasswordlessLogin.propTypes = {
    form: PropTypes.object,
    handleForgotPasswordClick: PropTypes.func,
    handlePasswordlessLoginClick: PropTypes.func,
    isSocialEnabled: PropTypes.bool,
    idps: PropTypes.arrayOf(PropTypes.string),
    hideEmail: PropTypes.bool,
    setLoginType: PropTypes.func
}

export default PasswordlessLogin

{"result":"{
  "id": "19420",
  "key": "SFCC-859",
  "summary": "Enhancement – Delivery Address & Customer-Editable Field Validation (Special Character & Regex Controls)",
  "description": "## Background\n\nOn the current Magento platform, unvalidated customer-editable fields (address lines, name fields, etc.) are causing active production issues. Special characters — including Chinese characters, back slashes, and newline delimiters — are being entered into these fields and corrupting flat files sent to 3PLs, causing shipping label generation to fail and orders not reaching dispatch.\n\nThe Omnichannel team has to catch and flag corrupted orders manually as there is no easy way to identify them in bulk. A sprint has been planned on Magento for September to fix this, but the priority is to ensure the same risk is not carried into SFCC.\n\nRelated Magento ticket: https://jira.tryzens.com/browse/ZOPOPT-2381\n\n## Requirements\n\n- Validate all customer-editable fields (address, name, etc.) to prevent special characters — specifically Chinese characters, back slashes, and newline delimiters — from being accepted\n- Confirm whether the current SFCC solution prevents this issue, and if not, what validations or controls are planned to mitigate it\n\n## Contacts\n\n  - **Raised by*: Lucy Fu (Digital PM, Zimmermann) / Billy Kwan (Zimmermann Operations)\n  - **Accenture*: Jasmijn Tsang, Natasha Lay, Tim Lavelle",
